"""Append source-grounded session, blinding, carrier and custody findings."""
import hashlib,json,pathlib
H=pathlib.Path(__file__).resolve().parent;P='additional_pfp_infrastructure_remaining';f=json.loads((H/(P+'_preparation.json')).read_text())['files'];rp=H/(P+'.json');r=json.loads(rp.read_text())
def ev(i,a,b):return {'path':f[i]['path'],'sha256':f[i]['sha256'],'lines':[a,b]}
rows=[
('027','C006 repair objective admits a universal zero replacement','CUT accepts any full integer cochain with lower Phi1 or zero, without preserving original edge claims or minimizing displacement. For every admitted graph, choose c=0 and potential alpha=0. Then c-d0*alpha=0 exactly, hence weighted Phi1=0, so CUT followed by VERIFY solves the declared task in two moves. This is a constructive mathematical task-selection limit, not an invalid certificate or a freshly executed native run.',[ev(165,189,233),ev(165,88,125),ev(165,308,324)],[],'If the intended comparison is nearest-original repair, bind the original cochain and edit objective or protected coordinates; otherwise describe the easier zero-defect replacement task explicitly.'),
('028','Fuel exhaustion is labelled as an obstruction','The session assigns SURVIVOR_OBSTRUCTION whenever fuel is exhausted without another terminal result. That branch does not construct a nonexistence witness. In fact the unrestricted task has the zero replacement solution described in F027.',[ev(165,237,260)],[],'Use a distinct resource-exhausted or unresolved status; reserve mathematical obstruction for a checked obstruction certificate.'),
('029','Formal matrix blinding only filters top-level answer keys','participant_view drops selected top-level keys, but copies nested values intact; a synthetic context.expected survives. Custom prompt builders receive the entire case. Thus the blanket statement that prompts never carry answer-bearing fields relies on caller discipline.',[ev(160,37,38),ev(160,75,90),ev(160,293,315)],['PFPINFRA-P036'],'Use an explicit allowlisted participant schema per task and validate the final rendered prompt; document custom-builder trust rather than claiming automatic recursive blinding.'),
('030','Release gate can report empty parity and abort later layers','A runner returning exit0 with empty output produces SATISFIED0/0 for host parity. A ReleaseGateError from the first layer aborts construction of all remaining findings, contradicting the promise to run every layer independently. Overall release remains blocked by the deliberately unavailable Lean layer.',[ev(237,296,325),ev(237,370,388)],['PFPINFRA-P037','PFPINFRA-P038'],'Require nonempty expected host/package coverage and convert each layer exception into its own unavailable/violated finding while continuing the remaining layers.'),
('031','Algebraic DTOs admit coercion, mutation and non-matrix carriers','The MSSN model file claims strict immutable algebraic schemas, but ExactRational coerces Boolean numerator and permits later denominator=0 assignment. Nilpotent and CSS validators omit rectangularity; ragged rows pass, including a nilpotence column omitted by first-row width. This concerns these DTOs, not the stricter deciding seed checker.',[ev(224,1,5),ev(224,53,86),ev(224,214,263)],['PFPINFRA-P040','PFPINFRA-P041','PFPINFRA-P042'],'Admit strict finite rectangular integer/binary carriers, validate all dimensions, and enforce immutability/assignment validation if downstream callers rely on the constructor invariant.'),
('032','Tournament hash does not commit the full receipt or observed exchange','canonical_digest hashes only a subset of round fields. Target operation, tolerance, per-round model, gate count and status reason can change without changing this digest; provider observations and referee source pins are outside it. Source existence and an unsigned summary digest cannot establish replayable full evidence custody.',[ev(141,108,144),ev(141,429,472)],[],'Hash a canonical complete task/candidate/receipt/observation manifest and pin referee sources; retain the existing explicit SO/noise-only interpretation.'),
]
items={x['id']:x for x in r['findings']}
for id,title,detail,refs,probes,action in rows:items['PFPINFRA-F'+id]={'id':'PFPINFRA-F'+id,'severity':'medium','title':title,'finding':detail,'evidence':refs,'probes':probes,'next_action':action,'status':'open','scope':'Exact identified source boundary. Constructive argument, synthetic control, historical evidence and runtime replay remain distinct.'}
r['findings']=list(items.values());c={x['id']:x for x in r['claims']}
c['PFPINFRA-C011']={'id':'PFPINFRA-C011','claim':'Source-bound code-change checking binds frozen source/task/candidate/patch and host binary policy, uses continuing finite budgets, and accepts only same-instance issued evidence for replay.','evidence':[ev(144,77,143),ev(144,163,217),ev(144,230,366)],'dependencies':['Trusted sequential host composition and native gate owner','Exact binary hash before/after execution','Absence of privileged concurrent replacement'],'limitations':['Snapshot commitment is not source execution, patch application or semantic correctness. Native syntax/path checks expressly have finite diagnostic scope. No fresh native run.']}
c['PFPINFRA-C012']={'id':'PFPINFRA-C012','claim':'coverage_at_k implements the exact finite without-replacement success count 1-C(n-c,k)/C(n,k). Independent enumeration matched all240 parameter triples with1<=n<=8.','evidence':[ev(240,32,36),ev(240,90,135)],'dependencies':['Exact integer counts and rational arithmetic','For sampling interpretation, appropriate exchangeability/independence assumptions'],'limitations':['Unique IDs/seeds and distinct judge functions do not prove empirical independence. No model sampling occurred.']}
c['PFPINFRA-C013']={'id':'PFPINFRA-C013','claim':'Catalog owners contain actual finite rational/chain/Pauli operations and conditional obstruction certificates, including zero-gap primal-dual equality, checked Hodge reconstruction, Kraus completeness and protected tensor-cycle pairings.','evidence':[ev(231,91,104),ev(232,167,233),ev(230,697,813),ev(230,908,927)],'dependencies':['Declared finite carriers, coefficient fields and tensor factor identity','SymPy/Pauli/native/Lean owners where invoked','Specific task caller routes'],'limitations':['Many catalog fields are expected reference labels. Generic seed check mostly compares computed reference equality, bypassing advanced_check-specific replay hooks. SymPy absent: no fresh execution of these owners, and no physical derivation or universal provider-effectiveness claim.']}
c['PFPINFRA-C014']={'id':'PFPINFRA-C014','claim':'Empirical comparison adapter replays actual provider wire hashes/lengths, mediated requests, returned model, usage/accounting status and task envelope before retaining measurements; injection scores are recalculated by supplied host oracle.','evidence':[ev(219,221,351),ev(219,532,617)],'dependencies':['Existing provider parser/accounting owner and original oracle adequacy','Pinned public task and source representation'],'limitations':['Content integrity is not ledger authentication. Token-amortization fences omit mathematical answer correctness. Paired finite observations and thresholds do not prove universal containment, generalization or superiority; no collection executed.']}
r['claims']=list(c.values());v={x['path']:x for x in r['validation']}
for suffix,count in [('07',4),('08',3)]:
 vp=P+'_checks'+suffix+'.json';b=(H/vp).read_bytes();j=json.loads(b);v[vp]={'path':vp,'sha256':hashlib.sha256(b).hexdigest(),'controls':count,'reproduced':count,'not_run':0,'python':j['python'],'scope':j['method']}
r['validation']=list(v.values());rp.write_text(json.dumps(r,indent=2)+'\n')
(H/(P+'.md')).write_text(f"# PFP infrastructure audit — in progress\n\n{r['full_source_read_count']}/{r['scope_count']} frozen files have complete substantive body reviews; {r['bounded_review_count']} have bounded dispositions and {len(r['remaining_work'])} remain. Parsing alone earns no full reading credit.\n\n{len(r['claims'])} synthesis claims and {len(r['findings'])} findings distinguish executable predicates from declarations and evidence custody. Principal defects include four rational methods with undefined variables, unchecked normal-form route outcomes, weak metadata admissions, provider/trace binding gaps, incorrect scaled numeric multiplicity and algebraic DTO carrier/mutation gaps. C006 also admits a universal all-zero replacement: valid for its declared task, insufficient evidence of nearest-original repair.\n\nPositive mechanisms include exact finite sum checking, rational L1 zero-gap replay, integer SNF with625 small-matrix controls, complete raw/request checks in the empirical adapter, source/candidate-bound code-change diagnostics and explicit limits on live/fixture and SO/noise evidence. These are conditional mechanisms, not universal physical or empirical claims.\n\n41 offline controls reproduced; one symbolic parser control remains not run because SymPy is absent. Existing Python3.12 supplied NumPy for earlier controls; no installs, providers, native builds, private benchmark reads or original edits. Exact pins/ranges and pending scope are in JSON.\n")
print(json.dumps({'full':r['full_source_read_count'],'remaining':len(r['remaining_work']),'claims':len(r['claims']),'findings':len(r['findings']),'reproduced_controls':41,'not_run':1}))
